   302    inline bool check_range (const void *base, unsigned int len) const
   303    {
   304      const char *p = (const char *) base;
   305      bool ok = this->max_ops-- > 0 &&
   306                this->start <= p &&
   307                p <= this->end &&
   308                (unsigned int) (this->end - p) >= len;
   309
   310      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   311         "check_range [%p..%p] (%d bytes) in [%p..%p] -> %s",
   312         p, p + len, len,
   313         this->start, this->end,
   314         ok ? "OK" : "OUT-OF-RANGE");
   315
   316      return likely (ok);
   317    }
