   319    template <typename T>
   320    inline bool check_array (const T *base, unsigned int len, unsigned int record_size = T::static_size) const
   321    {
   322      const char *p = (const char *) base;
   323      bool overflows = hb_unsigned_mul_overflows (len, record_size);
   324      unsigned int array_size = record_size * len;
   325      bool ok = !overflows && this->check_range (base, array_size);
   326
   327      DEBUG_MSG_LEVEL (SANITIZE, p, this->debug_depth+1, 0,
   328         "check_array [%p..%p] (%d*%d=%d bytes) in [%p..%p] -> %s",
   329         p, p + (record_size * len), record_size, len, (unsigned int) array_size,
   330         this->start, this->end,
   331         overflows ? "OVERFLOWS" : ok ? "OK" : "OUT-OF-RANGE");
   332
   333      return likely (ok);
   334    }
